import{_ as a,a as r,c as t,ac as i}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"白色巨塔（2003）","description":"大学医院的外科医生财前五郎拥有出众技术，也渴望在组织中取得更高位置；内科医生里见修二更坚持从患者需要出发。晋升、资源和名望不断介入医疗工作，两人的道路因此形成对照。","frontmatter":{"title":"白色巨塔（2003）","description":"大学医院的外科医生财前五郎拥有出众技术，也渴望在组织中取得更高位置；内科医生里见修二更坚持从患者需要出发。晋升、资源和名望不断介入医疗工作，两人的道路因此形成对照。","media":{"category":"series","year":2003,"doubanRating":9.7,"ratingCheckedAt":"2026-10-31","ratingSource":"https://www.douban.com/doulist/134440083/","ratingSourceType":"豆瓣公开片单"},"showdocs":{"topics":[{"id":"personal","title":"生活记录","link":"/topics/personal/"}],"kind":"影视导读","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"影视 · 电视剧","summary":"大学医院的外科医生财前五郎拥有出众技术，也渴望在组织中取得更高位置；内科医生里见修二更坚持从患者需要出发。晋升、资源和名望不断介入医疗工作，两人的道路因此形成对照。","status":"active","related":[{"title":"大明王朝1566","link":"/life/personal/media/series/ming-dynasty-1566","kind":"影视导读","scope":"general","audience":"general"},{"title":"是，大臣 第一季","link":"/life/personal/media/series/yes-minister-season-1","kind":"影视导读","scope":"general","audience":"general"},{"title":"红楼梦（1987）","link":"/life/personal/media/series/dream-of-the-red-chamber-1987","kind":"影视导读","scope":"general","audience":"general"},{"title":"西游记（1986）","link":"/life/personal/media/series/journey-to-the-west-1986","kind":"影视导读","scope":"general","audience":"general"},{"title":"老友记 第一季","link":"/life/personal/media/series/friends-season-1","kind":"影视导读","scope":"general","audience":"general"},{"title":"请回答1988","link":"/life/personal/media/series/reply-1988","kind":"影视导读","scope":"general","audience":"general"},{"title":"毛骗 终结篇","link":"/life/personal/media/series/moral-peanuts-finale","kind":"影视导读","scope":"general","audience":"general"},{"title":"武林外传","link":"/life/personal/media/series/my-own-swordsman","kind":"影视导读","scope":"general","audience":"general"},{"title":"我的团长我的团","link":"/life/personal/media/series/my-chief-and-my-regiment","kind":"影视导读","scope":"general","audience":"general"},{"title":"非自然死亡","link":"/life/personal/media/series/unnatural","kind":"影视导读","scope":"general","audience":"general"},{"title":"机智医生生活 第一季","link":"/life/personal/media/series/hospital-playlist-season-1","kind":"影视导读","scope":"general","audience":"general"},{"title":"亮剑","link":"/life/personal/media/series/bright-sword","kind":"影视导读","scope":"general","audience":"general"},{"title":"琅琊榜","link":"/life/personal/media/series/nirvana-in-fire","kind":"影视导读","scope":"general","audience":"general"},{"title":"后宫·甄嬛传","link":"/life/personal/media/series/empresses-in-the-palace","kind":"影视导读","scope":"general","audience":"general"},{"title":"漫长的季节","link":"/life/personal/media/series/the-long-season","kind":"影视导读","scope":"general","audience":"general"},{"title":"我们与恶的距离","link":"/life/personal/media/series/the-world-between-us","kind":"影视导读","scope":"general","audience":"general"}],"prev":{"text":"请回答1988","link":"/life/personal/media/series/reply-1988"},"next":{"text":"毛骗 终结篇","link":"/life/personal/media/series/moral-peanuts-finale"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"请回答1988","link":"/life/personal/media/series/reply-1988"},"next":{"text":"毛骗 终结篇","link":"/life/personal/media/series/moral-peanuts-finale"}},"headers":[],"relativePath":"life/personal/media/series/the-white-tower-2003.md","filePath":"life/personal/media/series/the-white-tower-2003.md"}'),n={name:"life/personal/media/series/the-white-tower-2003.md"};function l(o,e,s,d,p,h){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="白色巨塔-2003" tabindex="-1">白色巨塔（2003） <a class="header-anchor" href="#白色巨塔-2003" aria-label="Permalink to &quot;白色巨塔（2003）&quot;">​</a></h1><p><a href="./../overview">影视总览</a> · <a href="./overview">电视剧片单</a></p><h2 id="基本资料" tabindex="-1">基本资料 <a class="header-anchor" href="#基本资料" aria-label="Permalink to &quot;基本资料&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>信息</th></tr></thead><tbody><tr><td>原名 / 别名</td><td>白い巨塔 / The Great White Tower</td></tr><tr><td>年份 / 地区</td><td>2003 / 日本</td></tr><tr><td>类型</td><td>剧情 / 医疗 / 职场</td></tr><tr><td>导演 / 主创</td><td>西谷弘、河野圭太等；原著山崎丰子</td></tr><tr><td>主要演员 / 配音</td><td>唐泽寿明、江口洋介、黑木瞳</td></tr><tr><td>篇幅 / 版本</td><td>21 集，单集约 45 分钟；特别篇另计</td></tr><tr><td>豆瓣参考评分</td><td><strong>9.7 / 10</strong></td></tr><tr><td>评分依据</td><td><a href="https://www.douban.com/doulist/134440083/" target="_blank" rel="noopener noreferrer">豆瓣用户维护的电视剧片单</a>（豆瓣公开片单）</td></tr><tr><td>查询日期</td><td>2026-10-31</td></tr></tbody></table><p>评分为本次查询可读取的豆瓣页面值，网页缓存可能滞后，不能保证与此刻实时值一致。 篇幅按常见版本作近似说明，片头、花絮及剪辑差异可能影响播放时长。</p><h2 id="创作背景与资料" tabindex="-1">创作背景与资料 <a class="header-anchor" href="#创作背景与资料" aria-label="Permalink to &quot;创作背景与资料&quot;">​</a></h2><p>富士电视台官方介绍确认，本版改编山崎丰子作品，将舞台更新到当时的现代，计划通过取材保持职业真实感，全剧21集。井上由美子参与剧本改编，故事由教授竞争逐渐进入医疗责任与司法过程。<a href="https://www.fujitv.co.jp/b_hp/shiroikyoto/index.html" target="_blank" rel="noopener noreferrer">富士电视台节目资料</a>、<a href="https://www.fujitv.co.jp/b_hp/shiroikyoto/backnumber/503000008-1.html" target="_blank" rel="noopener noreferrer">官方第一集简介</a></p><p>这样的更新不是只替换设备和服装，而是重新安排专业权威如何与组织、患者及公共判断发生关系。</p><h2 id="剧情介绍" tabindex="-1">剧情介绍 <a class="header-anchor" href="#剧情介绍" aria-label="Permalink to &quot;剧情介绍&quot;">​</a></h2><p>大学医院的外科医生财前五郎拥有出众技术，也渴望在组织中取得更高位置；内科医生里见修二更坚持从患者需要出发。晋升、资源和名望不断介入医疗工作，两人的道路因此形成对照。</p><p>剧集并未把冲突停留在个性不同上，而是展示医院如何同时是治疗机构、学术组织和权力网络。患者及其家属的经验，使专业判断背后的责任变得无法回避。</p><h2 id="特色与看点" tabindex="-1">特色与看点 <a class="header-anchor" href="#特色与看点" aria-label="Permalink to &quot;特色与看点&quot;">​</a></h2><h3 id="_1-叙事与人物" tabindex="-1">1. 叙事与人物 <a class="header-anchor" href="#_1-叙事与人物" aria-label="Permalink to &quot;1. 叙事与人物&quot;">​</a></h3><p>会议、选举、查房与诊室分别采用不同的交流规则。观察同一个人在不同场合如何说话，能看见专业权威与组织地位之间并不总是重合。</p><h3 id="_2-主题与表达" tabindex="-1">2. 主题与表达 <a class="header-anchor" href="#_2-主题与表达" aria-label="Permalink to &quot;2. 主题与表达&quot;">​</a></h3><p>财前的能力和野心相互支持，也相互遮蔽；里见的坚持同样会付出代价。作品的力量在于让人物保留复杂性，而不是只提供一个正确榜样。</p><h2 id="财前与里见为何不能简单二分" tabindex="-1">财前与里见为何不能简单二分 <a class="header-anchor" href="#财前与里见为何不能简单二分" aria-label="Permalink to &quot;财前与里见为何不能简单二分&quot;">​</a></h2><p>财前有真正的技术能力，也渴望被承认，他将更高职位理解为扩大事业的必要条件。里见重视病人和证据，却不擅长维护组织中的关系。两人的分歧并不等于能力与良心只能二选一，而在于每次冲突时如何排列专业、名望和责任。</p><p>东教授的退场焦虑、岳父的资源动员、年轻医生的依附与恐惧，让医院成为多层关系。患者家属进入后，这套内部自洽的语言才受到外部生活经验的挑战。</p><h2 id="两部分结构的观看路线" tabindex="-1">两部分结构的观看路线 <a class="header-anchor" href="#两部分结构的观看路线" aria-label="Permalink to &quot;两部分结构的观看路线&quot;">​</a></h2><p>前半段围绕教授选举，关注支持如何形成、礼物和人情怎样改变判断；后半段转向诊疗后果与举证，关注当事人是否能够得到清楚解释。前面看似社交性的细节，会在后面变成证言和立场问题。</p><p>建议记下某个角色第一次判断与后来公开说法的差别：是获得新证据后修正，还是因为位置变化而调整？作品的紧张感常来自这两者难以区分。</p><h2 id="代表场景-查房与法庭" tabindex="-1">代表场景：查房与法庭 <a class="header-anchor" href="#代表场景-查房与法庭" aria-label="Permalink to &quot;代表场景：查房与法庭&quot;">​</a></h2><p>查房时，一群人围绕床位移动，患者既在中心，又可能最难插话。法庭把原本由专业权威决定的说明重新公开，词语、记录和记忆都开始接受质询。场景变化使同一个人必须用另一种方式为自己解释。</p><p>音乐与肃穆建筑强化机构的庄严，私人谈话却不断显出嫉妒、利益和恐惧。宏伟外观与具体人的局限形成标题中的“巨塔”感。</p><h2 id="评价与现实距离" tabindex="-1">评价与现实距离 <a class="header-anchor" href="#评价与现实距离" aria-label="Permalink to &quot;评价与现实距离&quot;">​</a></h2><p>本剧擅长保留人物矛盾，技术高明不会自动成为道德豁免，原则正确也不意味着行动没有代价。其戏剧结构高度集中，观众不宜将单个案件推成对所有医生或医院的判断。</p><p>看完可区分能力、沟通和可追责性：三者都重要，却不能彼此替代。对医疗职业的敬重与要求清晰说明并不冲突，这比把角色分成值得信任和永不信任的两类，更接近作品留下的复杂问题。</p><h2 id="适合谁看与观看建议" tabindex="-1">适合谁看与观看建议 <a class="header-anchor" href="#适合谁看与观看建议" aria-label="Permalink to &quot;适合谁看与观看建议&quot;">​</a></h2><p>适合喜欢严肃职场、伦理冲突与长线人物弧光的人。前半段铺设关系较慢，建议连贯观看。医疗与诉讼情节服务于故事，具体制度和技术也有时代背景。</p><h2 id="看后思考" tabindex="-1">看后思考 <a class="header-anchor" href="#看后思考" aria-label="Permalink to &quot;看后思考&quot;">​</a></h2><p>能力出众是否足以保证一个人作出可靠判断？当机构声誉与患者利益冲突时，谁应承担说明责任？</p><p>创作事实见段落所附来源；人物、场景与评价部分为本站观影分析，不代表主创唯一解释。正文保留主要故事体验，不展开关键结局。评分用于辅助选片，不代表每位观众的感受。</p><h2 id="资料与复核入口" tabindex="-1">资料与复核入口 <a class="header-anchor" href="#资料与复核入口" aria-label="Permalink to &quot;资料与复核入口&quot;">​</a></h2><ul><li><a href="https://www.douban.com/doulist/134440083/" target="_blank" rel="noopener noreferrer">豆瓣用户维护的电视剧片单</a>：本页评分依据；查询于 2026-10-31。</li><li><a href="https://movie.douban.com/subject/2150220/" target="_blank" rel="noopener noreferrer">《白色巨塔（2003）》豆瓣条目</a>：版本与后续评分复核入口；部分条目可能要求验证。</li></ul><p><a href="./overview">返回电视剧片单</a> · <a href="./../overview">返回影视总览</a></p>',36)])])}const f=a(n,[["render",l]]);export{u as __pageData,f as default};
